 2	// EventTarget removal detaches reception; an already started decode still settles.
 3	export function subscribeChannel(channel, bootstrapMode, receive) {
 4	  const listener = (event) => {
 5	    const decoded = channel.decode(event.detail);
 6	    if (decoded && typeof decoded.then === "function") decoded.then(receive);
 7	    else receive(decoded);
 8	  };
